using System;using System.IO;using System.Net;using System.Text;using System.Text.RegularExpressions;using System.Web.Script.Serialization;using System.Collections.Generic;
public sealed class QuotaPhone {
 readonly string path;public QuotaPhone(string folder){path=Path.Combine(folder,"wechat-serverchan-key.dat");}
 public bool HasKey{get{return File.Exists(path);}}
 public void SaveKey(string key){key=(key??"").Trim();if(!Regex.IsMatch(key,@"^SCT[A-Za-z0-9_-]{10,180}$"))throw new ArgumentException("请输入 Server酱 Turbo 的 SCT 开头 SendKey。");Directory.CreateDirectory(Path.GetDirectoryName(path));byte[] data=LocalProtection.Protect(Encoding.UTF8.GetBytes(key));string temp=path+".tmp";File.WriteAllBytes(temp,data);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
 public void RemoveKey(){if(File.Exists(path))File.Delete(path);}
 internal static bool Accepted(string response){try{var d=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(response);object code;return d!=null&&d.TryGetValue("code",out code)&&Convert.ToString(code)=="0";}catch(ArgumentException){return false;}catch(InvalidOperationException){return false;}}
 internal static string SendRequest(Uri endpoint,string title,string body){if(endpoint.Scheme!="https"&&!(endpoint.Scheme=="http"&&endpoint.IsLoopback))throw new ArgumentException("推送地址无效。");ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var req=(HttpWebRequest)WebRequest.Create(endpoint);req.Method="POST";req.AllowAutoRedirect=false;req.Timeout=10000;req.ReadWriteTimeout=10000;req.ContentType="application/x-www-form-urlencoded";byte[] data=Encoding.UTF8.GetBytes("title="+Uri.EscapeDataString(title)+"&desp="+Uri.EscapeDataString(body));req.ContentLength=data.Length;using(var output=req.GetRequestStream())output.Write(data,0,data.Length);using(var response=(HttpWebResponse)req.GetResponse())using(var reader=new StreamReader(response.GetResponseStream())){char[] buffer=new char[65537];int n=reader.ReadBlock(buffer,0,buffer.Length);if(n>65536)return "推送服务响应过大";return Accepted(new string(buffer,0,n))?"推送服务已接受；手机是否收到请自行确认":"推送服务未接受消息，请检查账号和通道";}}
 public string Send(string title,string body){if(!HasKey)return "尚未配置微信推送密钥";try{string key=Encoding.UTF8.GetString(LocalProtection.Unprotect(File.ReadAllBytes(path)));if(!Regex.IsMatch(key,@"^SCT[A-Za-z0-9_-]{10,180}$"))return "微信推送密钥无效";return SendRequest(new Uri("https://sctapi.ftqq.com/"+key+".send"),title,body);}catch(Exception e){if(!(e is IOException)&&!(e is UnauthorizedAccessException)&&!(e is WebException)&&!(e is System.Security.Cryptography.CryptographicException)&&!(e is ArgumentException))throw;return "微信推送失败，请检查密钥、网络和通道";}}
}
